code_sketch:
struct msg { int64_t expires_ms; /* CLOCK_MONOTONIC ms, 0 = never */ char *body; };

static int64_t mono_ms(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (int64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

/* consumer: last line of defence before the work is done */
if (msg->expires_ms != 0 && mono_ms() >= msg->expires_ms)
    dead_letter(msg, "expired");
else
    dispatch(msg);
